async ({ shell: { exec } }) => {
  await exec("sleep 15");
  const id = (await exec("gh run list --workflow release.yml --limit 1 --json databaseId --jq '.[0].databaseId'")).stdout.trim();
  const w = await exec(`gh run watch ${id} --exit-status --interval 15 2>&1 | tail -4`, { timeoutMs: 260000 });
  const r = await exec("gh release view v2.5.1 --json isDraft,url,body 2>&1; git ls-remote --tags origin v2 v2.5.1");
  return { id, w: w.stdout, code: w.code, r: r.stdout };
}
